import{_ as e,o,c as i,ah as n}from"./chunks/framework.DXIPeQh2.js";const s="/projects/ROSMan/en/latest/assets/image2.B_t6n1eL.png",a="/projects/ROSMan/en/latest/assets/image1.CI_ERqLi.png",r="/projects/ROSMan/en/latest/assets/image3.CUL5oPeS.png",l="/projects/ROSMan/en/latest/assets/image4.CAMPRI9E.png",c="/projects/ROSMan/en/latest/assets/image5.BTv21rv4.png",g="data:image/png;base64,",h="data:image/png;base64,",d="data:image/png;base64,",m="data:image/png;base64,",p="data:image/png;base64,",u="data:image/png;base64,",A="/projects/ROSMan/en/latest/assets/image13.CKC6G2g7.png",f="data:image/png;base64,",b="/projects/ROSMan/en/latest/assets/image15.GhYeP1fE.png",y="data:image/png;base64,",x="data:image/png;base64,",w="data:image/png;base64,",k="data:image/png;base64,",S="data:image/png;base64,",q="data:image/png;base64,",R="data:image/png;base64,",v="/projects/ROSMan/en/latest/assets/image6.W0-I3t9R.png",z="/projects/ROSMan/en/latest/assets/image2.BhL5MoEC.png",E="/projects/ROSMan/en/latest/assets/image3.6UuKEcDB.png",j="/projects/ROSMan/en/latest/assets/image4.ByUaFtJf.png",B="/projects/ROSMan/en/latest/assets/image5.BOHOGKXX.png",I="/projects/ROSMan/en/latest/assets/image2.WRhl7NLx.png",T="/projects/ROSMan/en/latest/assets/image7.bZn6X6Be.png",U="/projects/ROSMan/en/latest/assets/image8.B4-41W7V.png",G="/projects/ROSMan/en/latest/assets/image9.vqbPVJgy.png",O="/projects/ROSMan/en/latest/assets/image10.CRqHR-0R.png",C="/projects/ROSMan/en/latest/assets/image13.DH0NTzsR.png",M="/projects/ROSMan/en/latest/assets/image14.DaWFEv0x.png",D="/projects/ROSMan/en/latest/assets/image15.CG3pr7fD.png",N="/projects/ROSMan/en/latest/assets/image16.pkMRFTfh.png",F="/projects/ROSMan/en/latest/assets/image17.DCYG_v-T.png",X="/projects/ROSMan/en/latest/assets/image18.CyvbEU9H.png",Q="/projects/ROSMan/en/latest/assets/image19.B6ihSJg-.png",P="/projects/ROSMan/en/latest/assets/image20.BJF7qGMB.png",H="/projects/ROSMan/en/latest/assets/image21.BiBHaOX5.png",Y="/projects/ROSMan/en/latest/assets/image22.ZSuWjhYw.png",L="/projects/ROSMan/en/latest/assets/image23.DtOMjiLr.png",J="/projects/ROSMan/en/latest/assets/image24.c_ycWRoQ.png",Z="/projects/ROSMan/en/latest/assets/image25.DHhagaBz.png",V="/projects/ROSMan/en/latest/assets/image26.CWCIqO-z.png",K="/projects/ROSMan/en/latest/assets/image2.CORpTuql.png",W="/projects/ROSMan/en/latest/assets/image3.CWNYmI5M.png",_="/projects/ROSMan/en/latest/assets/image4.esPj-xJ_.png",$="/projects/ROSMan/en/latest/assets/image2.WRhl7NLx.png",tt="data:image/png;base64,",et="/projects/ROSMan/en/latest/assets/image4.C6YDzbc0.png",ot="/projects/ROSMan/en/latest/assets/image5.BPuhMjDy.png",it="/projects/ROSMan/en/latest/assets/image6.U425irQD.png",nt="/projects/ROSMan/en/latest/assets/image7.DjzggrAN.png",st="/projects/ROSMan/en/latest/assets/image8.Bu6rdWdT.png",at="/projects/ROSMan/en/latest/assets/image9.BViUt4Ip.png",rt="/projects/ROSMan/en/latest/assets/image10.Bz5BXUNj.png",lt="data:image/png;base64,",ct="/projects/ROSMan/en/latest/assets/image12.CzqB2gSt.png",gt="/projects/ROSMan/en/latest/assets/image13.ByJA3lkc.png",ht="/projects/ROSMan/en/latest/assets/image14.BK8rvBW3.png",dt="/projects/ROSMan/en/latest/assets/image15.Dh4nKpW_.png",mt="/projects/ROSMan/en/latest/assets/image16.DsHGgPie.png",kt=JSON.parse('{"title":"5. ROS Robot Simulation Model & URDF","description":"","frontmatter":{},"headers":[],"relativePath":"docs/5.ROS_Robot_Simulation_Model_URDF.md","filePath":"docs/5.ROS_Robot_Simulation_Model_URDF.md"}'),pt={name:"docs/5.ROS_Robot_Simulation_Model_URDF.md"};function ut(At,t,ft,bt,yt,xt){return o(),i("div",null,[...t[0]||(t[0]=[n(`<h1 id="_5-ros-robot-simulation-model-urdf" tabindex="-1">5. ROS Robot Simulation Model &amp; URDF <a class="header-anchor" href="#_5-ros-robot-simulation-model-urdf" aria-label="Permalink to &quot;5. ROS Robot Simulation Model &amp; URDF&quot;">​</a></h1><h2 id="_5-1-introduction-to-urdf-models-and-getting-started" tabindex="-1">5.1 Introduction to URDF Models and Getting Started <a class="header-anchor" href="#_5-1-introduction-to-urdf-models-and-getting-started" aria-label="Permalink to &quot;5.1 Introduction to URDF Models and Getting Started&quot;">​</a></h2><h3 id="_5-1-1-urdf-model-introduction" tabindex="-1">5.1.1 URDF Model Introduction <a class="header-anchor" href="#_5-1-1-urdf-model-introduction" aria-label="Permalink to &quot;5.1.1 URDF Model Introduction&quot;">​</a></h3><p>The Unified Robot Description Format (URDF) is an XML file format widely used in ROS (Robot Operating System) to comprehensively describe all components of a robot.</p><p>Robots are typically composed of multiple links and joints. A link is defined as a rigid object with certain physical properties, while a joint connects two links and constrains their relative motion.</p><p>By connecting links with joints and imposing motion restrictions, a kinematic model is formed. The URDF file specifies the relationships between joints and links, their inertial properties, geometric characteristics, and collision models.</p><h3 id="_5-1-2-comparison-between-xacro-and-urdf-model" tabindex="-1">5.1.2 Comparison between xacro and URDF Model <a class="header-anchor" href="#_5-1-2-comparison-between-xacro-and-urdf-model" aria-label="Permalink to &quot;5.1.2 Comparison between xacro and URDF Model&quot;">​</a></h3><p>The URDF model serves as a description file for simple robot models, offering a clear and easily understandable structure. However, when it comes to describing complex robot structures, using URDF alone can result in lengthy and unclear descriptions.</p><p>To address this limitation, the xacro model extends the capabilities of URDF while maintaining its core features. The xacro format provides a more advanced approach to describe robot structures. It greatly improves code reusability and helps avoid excessive description length.</p><p>For instance, when describing the two legs of a humanoid robot, the URDF model would require separate descriptions for each leg. On the other hand, the xacro model allows for describing a single leg and reusing that description for the other leg, resulting in a more concise and efficient representation.</p><h3 id="_5-1-3-basic-syntax-of-urdf-model" tabindex="-1">5.1.3 Basic Syntax of URDF Model <a class="header-anchor" href="#_5-1-3-basic-syntax-of-urdf-model" aria-label="Permalink to &quot;5.1.3 Basic Syntax of URDF Model&quot;">​</a></h3><ul><li><strong>XML Basic Syntax</strong></li></ul><p>The URDF model is written using XML standard.</p><p>(1) Elements:</p><p>An element can be defined as desired using the following formula:</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">element</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">element</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>(2) Properties:</p><p>Properties are included within elements to define characteristics and parameters. Please refer to the following formula to define an element with properties:</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">element</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">property_1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;property value1&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">property_2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;property value2&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">element</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>(3) Comments:</p><p>Comments have no impact on the definition of other properties and elements. Please use the following formula to define a comment:</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- comment content --&gt;</span></span></code></pre></div><ul><li><strong>Link</strong></li></ul><p>The Link element describes the visual and physical properties of the robot&#39;s rigid component. The following tags are commonly used to define the motion of a link:</p><img loading="lazy" height="113" width="506" class="common_img" src="`+s+'"><p>(1) &lt;visual&gt;：Describe the appearance of the link, such as size, color and shape.</p><p>(2) &lt;inertial&gt;：Describe the inertia parameters of the link, which will used in dynamics calculation.</p><p>(3) &lt;collision&gt;：Describe the collision inertia property of the link.</p><p>Each tag contains the corresponding child tag. The functions of the tags are listed below.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Tag</th><th style="text-align:left;">Function</th></tr></thead><tbody><tr><td style="text-align:left;">origin</td><td style="text-align:left;">Describe the pose of the link. It contains two parameters, including xyz and rpy. Xyz describes the pose of the link in the simulated map. Rpy describes the pose of the link in the simulated map.</td></tr><tr><td style="text-align:left;">mess</td><td style="text-align:left;">Describe the mess of the link</td></tr><tr><td style="text-align:left;">inertia</td><td style="text-align:left;">Describe the inertia of the link. As the inertia matrix is symmetrical, these six parameters need to be input, ixx, ixy, ixz, iyy, iyz and izz, as properties. These parameters can be calculated.</td></tr><tr><td style="text-align:left;">geometry</td><td style="text-align:left;">Describe the shape of the link. It uses mesh parameter to load texture file, and em[ploys filename parameters to load the path for texture file. It has three child tags, namely box, cylinder and sphere.</td></tr><tr><td style="text-align:left;">material</td><td style="text-align:left;">Describe the material of the link. The parameter name is the required filed. The tag color can be used to change the color and transparency of the link.</td></tr></tbody></table><p id="anchor_6_1_3_joint"></p><ul><li><strong>Joint</strong></li></ul><p>The &quot;<strong>Joint</strong>&quot; tag describes the kinematic and dynamic properties of the robot&#39;s joints, including the joint&#39;s range of motion, target positions, and speed limitations. In terms of motion style, joints can be categorized into six types.</p><img loading="lazy" height="747" width="802" src="'+a+'" class="common_img"><p>The following tags will be used to write joint motion.</p><img loading="lazy" height="153" width="294" src="'+r+'" class="common_img"><p>(1) <code>&lt;parent_link&gt;</code>：Parent link</p><p>(2) <code>&lt;child_link&gt;</code>：Child link</p><p>(3) <code>&lt;calibration&gt;</code>：Calibrate the joint angle</p><p>(4) <code>&lt;dynamics&gt;</code>：Describes some physical properties of motion</p><p>(5) <code>&lt;limit&gt;</code>：Describes some limitations of the motion</p><p>The function of each tag is listed below. Each tag involves one or several child tags.</p><table tabindex="0"><thead><tr><th style="text-align:center;">Tag</th><th style="text-align:center;">Function</th></tr></thead><tbody><tr><td style="text-align:center;">origin</td><td style="text-align:center;">Describe the pose of the parent link. It involves two parameters, including xyz and rpy. Both xyz and rpy describe the pose of the link in simulated map.</td></tr><tr><td style="text-align:center;">axis</td><td style="text-align:center;">Control the child link to rotate around any axis of the parent link.</td></tr><tr><td style="text-align:center;">limit</td><td style="text-align:center;">The motion of the child link is constrained using the lower and upper properties, which define the limits of rotation for the child link. The effort properties restrict the allowable force range applied during rotation (values: positive and negative; units: N). The velocity properties confine the rotational speed, measured in meters per second (m/s).</td></tr><tr><td style="text-align:center;">mimic</td><td style="text-align:center;">Describe the relationship between joints.</td></tr><tr><td style="text-align:center;">safety_controller</td><td style="text-align:center;">Describes the parameters of the safety controller used for protecting the joint motion of the robot.</td></tr></tbody></table><ul><li><strong>robot Tag</strong></li></ul><p>The complete top tags of a robot, including the <strong>&lt;link&gt;</strong> and <strong>&lt;joint&gt;</strong> tags, must be enclosed within the <strong>&lt;robot&gt;</strong> tag. The format is as follows:</p><img loading="lazy" height="152" width="235" src="'+l+'" class="common_img"><ul><li><strong>gazebo Tag</strong></li></ul><p>This tag is used in conjunction with the Gazebo simulator. Within this tag, you can define simulation parameters and import Gazebo plugins, as well as specify Gazebo&#39;s physical properties, and more.</p><img loading="lazy" height="71" width="295" src="'+c+'" class="common_img"><ul><li><strong>Write Simple URDF Model</strong></li></ul><p>(1) Name the model of the robot</p><p>To start writing the URDF model, we need to set the name of the robot following this format: &quot;<strong>&lt;robot name=&#39;robot model name&#39;&gt;</strong>&quot;. Lastly, input &quot;<strong>&lt;/robot&gt;</strong>&quot; at the end to represent that the model is written successfully.</p><img loading="lazy" height="42" width="188" src="'+g+'" class="common_img"><img loading="lazy" height="19" width="70" src="'+h+'" class="common_img"><p>(2) Set links</p><p>① To write the first link and use indentation to indicate that it is part of the currently set model. Set the name of the link using the following format: <strong>&lt;link name=&quot;link name&quot;&gt;</strong>. Finally, conclude with &quot;<strong>&lt;/link&gt;</strong>&quot; to indicate the successful completion of the link definition.</p><img loading="lazy" height="22" width="234" src="'+d+'" class="common_img"><img loading="lazy" height="22" width="80" src="'+m+'" class="common_img"><p>② Write the link description and use indentation to indicate that it is part of the currently set link, and conclude with &quot;<strong>&lt;/visual&gt;</strong>&quot;.</p><img loading="lazy" height="24" width="80" src="'+p+'" class="common_img"><img loading="lazy" height="28" width="80" src="'+u+'" class="common_img"><p>③ The &quot;<strong>&lt;geometry&gt;</strong>&quot; tag is employed to define the shape of a link. Once the description is complete, include &quot;<strong>&lt;/geometry&gt;</strong>&quot;. Within the &quot;<strong>&lt;geometry&gt;</strong>&quot; tag, indentation is used to specify the detailed description of the link&#39;s shape. The following example demonstrates a link with a cylindrical shape: &quot;<strong>&lt;cylinder length=&#39;0.01&#39; radius=&#39;0.2&#39;/&gt;</strong>&quot;. In this instance, &quot;<strong>length=&#39;0.01&#39;</strong>&quot; signifies a length of 0.01 meters for the link, while &quot;<strong>radius=&#39;0.2&#39;</strong>&quot; denotes a radius of 0.2 meters, resulting in a cylindrical shape.</p><img loading="lazy" height="73" width="376" src="'+A+'" class="common_img"><p>④ The &quot;<strong>&lt;origin&gt;</strong>&quot; tag is utilized to specify the position of a link, with indentation used to indicate the detailed description of the link&#39;s position. The following example demonstrates the position of a link: &quot;<strong>&lt;origin rpy=&#39;0 0 0&#39; xyz=&#39;0 0 0&#39; /&gt;</strong>&quot;. In this example, &quot;<strong>rpy</strong>&quot; represents the roll, pitch, and yaw angles of the link, while &quot;<strong>xyz</strong>&quot; represents the coordinates of the link&#39;s position. This particular example indicates that the link is positioned at the origin of the coordinate system.</p><img loading="lazy" height="17" width="300" src="'+f+'" class="common_img"><p>⑤ The &quot;<strong>&lt;material&gt;</strong>&quot; tag is used to define the visual appearance of a link, with indentation used to specify the detailed description of the link&#39;s color. To start describing the color, include &quot;<strong>&lt;material&gt;</strong>&quot;, and end with &quot;<strong>&lt;/material&gt;</strong>&quot; when the description is complete. The following example demonstrates setting a link color to yellow: &quot;<strong>&lt;color rgba=&#39;1 1 0 1&#39; /&gt;</strong>&quot;. In this example, &quot;<strong>rgba=&#39;1 1 0 1&#39;</strong>&quot; represents the color threshold for achieving a yellow color.</p><img loading="lazy" height="61" width="267" src="'+b+'" class="common_img"><p>(3) Set joint</p><p>① To write the first joint, use indentation to indicate that the joint belongs to the current model being set. Then, specify the name and type of the joint as follows: &quot;<strong>&lt;joint name=&#39;joint name&#39; type=&#39;joint type&#39;&gt;</strong>&quot;. Finally, include &quot;<strong>&lt;/joint&gt;</strong>&quot; to indicate the completion of the joint definition.</p><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>to learn about the type of the joint, please refer to &quot;<a href="#anchor_6_1_3_joint"><strong>5.1.3 Basic Syntax of URDF Model -&gt; joint</strong></a>&quot;.</p></section><img loading="lazy" height="20" width="400" src="'+y+'" class="common_img"><img loading="lazy" height="19" width="70" src="'+x+'" class="common_img"><p>② Write the description section for the connection between the link and the joint. Use indentation to indicate that it is part of the currently defined joint. The parent parameter and child parameter should be set using the following format: &quot;<strong>&lt;parent link=&#39;parent link&#39;/&gt;</strong>&quot;, and &quot;<strong>&lt;child link=&#39;child link&#39; /&gt;</strong>&quot;. With the parent link serving as the pivot, the joint rotates the child link.</p><img loading="lazy" height="43" width="218" src="'+w+'" class="common_img"><p>③ &quot;<strong>&lt;origin&gt;</strong>&quot; describes the position of the joint using indention. This example describes the position of the joint: &quot;<strong>&lt;origin xyz=&#39;0 0 0.1&#39; /&gt;</strong>&quot;. xyz is the coordinate of the joint.</p><img loading="lazy" height="22" width="200" src="'+k+'" class="common_img"><p>④ &quot;<strong>&lt;axis&gt;</strong>&quot; describes the position of the joint adopting indention. &quot;<strong>&lt;axis xyz=&quot;0 0 1&quot; /&gt;</strong>&quot; describes one posture of a joint. Xyz specifies the pose of the joint.</p><img loading="lazy" height="24" width="180" src="'+S+'" class="common_img"><p>⑤ &quot;<strong>&lt;limit&gt;</strong>&quot; imposes restrictions on the joint using indention. The below picture The &quot;<strong>&lt;limit&gt;</strong>&quot; tag is used to restrict the motion of a joint, with indentation indicating the specific description of the joint angle limitations. The following example describes a joint with a maximum force limit of 300 Newtons, an upper limit of 3.14 radians, and a lower limit of -3.14 radians. The settings are defined as follows: &quot;<strong>effort=&#39;joint force (N)&#39;, velocity=&#39;joint motion speed&#39;, lower=&#39;lower limit in radians&#39;, upper=&#39;upper limit in radians&#39;</strong>&quot;.</p><img loading="lazy" height="16" width="550" src="'+q+'" class="common_img"><p>⑥ &quot;<strong>&lt;dynamics&gt;</strong>&quot; describes the dynamics of the joint using indention. &quot;<strong>&lt;dynamics damping=&#39;50&#39; friction=&#39;1&#39; /&gt;</strong>&quot; describes dynamics parameters of a joint.</p><img loading="lazy" height="20" width="382" src="'+R+'" class="common_img"><p>The complete code is as below:</p><img loading="lazy" height="1391" width="972" src="'+v+'"><h2 id="_5-2-urdf-model-explanation" tabindex="-1">5.2 URDF Model Explanation <a class="header-anchor" href="#_5-2-urdf-model-explanation" aria-label="Permalink to &quot;5.2 URDF Model Explanation&quot;">​</a></h2><h3 id="_5-2-1-import-virtual-machine" tabindex="-1">5.2.1 Import Virtual Machine <a class="header-anchor" href="#_5-2-1-import-virtual-machine" aria-label="Permalink to &quot;5.2.1 Import Virtual Machine&quot;">​</a></h3><p>(1) Extract and import the virtual machine <a href="./.html">AiNex_vm.zip</a> stored in the folder <a href="./resources_download.html">Appendix-&gt; VMware Image-&gt;AiNex VM</a>.</p><img loading="lazy" height="91" width="85" class="common_img" src="'+z+'"><p>(2) Click-on &quot;<strong>File -&gt; Open</strong>&quot; in sequence.</p><img loading="lazy" height="171" width="761" class="common_img" src="'+E+'"><p>(3) Select &quot;<strong>AiNex_vm.ovf</strong>&quot; and click-on &quot;<strong>Open</strong>&quot;.</p><img loading="lazy" height="145" width="670" class="common_img" src="'+j+'"><p>(4) To begin, choose a name, such as &quot;<strong>AiNex_vm</strong>&quot;. Next, click on &quot;<strong>Browse</strong>&quot; to specify where the virtual machine will be stored. We suggest saving it on a solid-state drive (SSD) for better performance, as the speed of the storage disk impacts the virtual machine&#39;s speed. Finally, click &quot;<strong>Import</strong>&quot; to complete the process.</p><img loading="lazy" height="230" width="342" class="common_img" src="'+B+'"><p>(5) Click-on &quot;<strong>Power on this virtual machine</strong>&quot;, and wait for it to boot up completely.</p><img loading="lazy" height="129" width="314" class="common_img" src="'+I+'"><h3 id="_5-2-2-robot-model-description" tabindex="-1">5.2.2 Robot Model Description <a class="header-anchor" href="#_5-2-2-robot-model-description" aria-label="Permalink to &quot;5.2.2 Robot Model Description&quot;">​</a></h3><p>(1) To facilitate comprehension, the AiNex robot model can be described as comprising two legs, two arms, a control board, and a camera.</p><img loading="lazy" height="630" width="1018" class="common_img" src="'+T+'"><p>(2) Each leg of the robot consists of 6 joints and 4 links, with each joint corresponding to one servo.</p><img loading="lazy" height="723" width="1106" class="common_img" src="'+U+'"><p>(3) Each robot arm contains 5 joints and 4 links, with each joint corresponding to one servo.</p><img loading="lazy" height="530" width="1131" class="common_img" src="'+G+'"><p>(4) Robot&#39;s head is composed of a camera and a joint. The camera can be considered as a link.</p><img loading="lazy" height="693" width="1049" class="common_img" src="'+O+'"><h3 id="_5-2-3-open-urdf-model-file" tabindex="-1">5.2.3 Open URDF Model File <a class="header-anchor" href="#_5-2-3-open-urdf-model-file" aria-label="Permalink to &quot;5.2.3 Open URDF Model File&quot;">​</a></h3><p>(1) Open the terminal, and execute the following command &quot;<strong>cd /home/ubuntu/ros_ws/src/ainex_simulations/ainex_description/urdf</strong>&quot; to access URDF model file.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cd /home/ubuntu/ros_ws/src/ainex_simulations/ainex_description/urdf</span></span></code></pre></div><p>(2) Take &quot;<strong>ainex.urdf.xacro</strong>&quot; as example. Execute the command &quot;<strong>vim ainex.urdf.xacro</strong>&quot; to open URDF model using vim.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>vim ainex.urdf.xacro</span></span></code></pre></div><img loading="lazy" height="480" width="734" class="common_img" src="'+C+'"><h3 id="_5-2-4-urdf-model-analysis-and-understanding" tabindex="-1">5.2.4 URDF Model Analysis and Understanding <a class="header-anchor" href="#_5-2-4-urdf-model-analysis-and-understanding" aria-label="Permalink to &quot;5.2.4 URDF Model Analysis and Understanding&quot;">​</a></h3><ul><li><strong>URDF Model Structure</strong></li></ul><p>AiNex&#39;s URDF model file comprises five individual files: &quot;<strong>ainex.xacro</strong>&quot; &quot;<strong>ainex.urdf.xacro</strong>&quot; &quot;<strong>gazebo.xacro</strong>&quot; &quot;<strong>materials.xacro</strong>&quot; and &quot;<strong>transmissions.xacro</strong>&quot; These five components are integrated through the &quot;<strong>ainex.xacro</strong>&quot; file to create a comprehensive URDF model file. This integration allows for the simultaneous loading of the URDF model and Gazebo parameter settings when using the Gazebo simulator. Using this method, it becomes possible to conduct simulation analyses in Gazebo, covering aspects such as the robot&#39;s kinematics, dynamics, and collision detection.</p><img loading="lazy" height="400" width="746" class="common_img" src="'+M+'"><ul><li><strong>ainex.xacro Analysis</strong></li></ul><p>Two files, &quot;<strong>ainex.urdf.xacro</strong>&quot; and &quot;<strong>gazebo.xacro</strong>&quot;, are referenced using the &lt;xacro:include&gt; tag. The &quot;<strong>ainex.xacro</strong>&quot; file incorporates these two files into a single URDF model.</p><p>The &quot;<strong>ainex.urdf.xacro</strong>&quot; file serves as a definition file for the URDF model, encompassing information about the geometric shapes, mass parameters, coordinate systems, and various components of the robot, including links, joints, and sensors.</p><p>Conversely, the &quot;<strong>gazebo.xacro</strong>&quot; file contains parameter settings necessary for using this URDF model within the Gazebo simulator. These settings include parameters like friction coefficients, materials, collision detection, and more. These parameters cannot be directly represented in URDF and require the use of Gazebo&#39;s extension tags to describe them.</p><img loading="lazy" height="95" width="639" class="common_img" src="'+D+'"><ul><li><strong>ainex.urdf.xacro Analysis</strong></li></ul><p>This code primarily outlines the essential characteristics and structure of the robot model. The file contains the robot&#39;s various components, such as joints, sensors, and links, which together constitute the fundamental framework of the robot model. Due to its length, we will break it down into three sections and provide examples for each. These sections primarily encompass the following:</p><p>(1) Model Declaration and Property Definition</p><p>The &quot;<strong>robot</strong>&quot; tag specifies the robot model&#39;s name as &quot;<strong>ainex</strong>&quot; and links to the &quot;<strong>xacro</strong>&quot; library for using xacro features in the code. The &quot;<strong>include</strong>&quot; tag references two other xacro files, &quot;<strong>materials.xacro</strong>&quot; and &quot;<strong>transmissions.xacro</strong>&quot;, which define color materials and transmissions, respectively.</p><img loading="lazy" height="43" width="551" class="common_img" src="'+N+'"><p>&quot;<strong>property</strong>&quot; tag defines various property values, such as motor torque, motor vectors, damping, friction force, and so on.</p><img loading="lazy" height="114" width="681" class="common_img" src="'+F+'"><p>(2) Link Definition</p><p>The &quot;<strong>link</strong>&quot; tag defines a link, in this case, &quot;<strong>r_hip_yaw_link</strong>&quot;.</p><p>The &quot;<strong>inertial</strong>&quot; tag specifies the inertial parameters of the link, including mass, center of mass, and inertia tensor.</p><p>The &quot;<strong>visual</strong>&quot; tag defines the link&#39;s visual model, including mesh files and materials.</p><p>The &quot;<strong>collision</strong>&quot; tag defines the collision model for the link, using the same mesh files as the visual model.</p><img loading="lazy" height="610" width="933" class="common_img" src="'+X+'"><p>(3) Joint Definition</p><p>The &quot;<strong>joint</strong>&quot; tag defines a joint in the robot model, in this case, &quot;<strong>r_hip_yaw</strong>&quot;.</p><p>The &quot;<strong>type</strong>&quot; attribute specifies the type of the joint, here it&#39;s &quot;revolute&quot; (rotational).</p><p>The &quot;<strong>origin</strong>&quot; tag sets the position and orientation of the joint.</p><p>The &quot;<strong>parent</strong>&quot; and &quot;<strong>child</strong>&quot; attributes respectively define the parent and child links of the joint.</p><p>The &quot;<strong>axis</strong>&quot; tag defines the rotation axis of the joint.</p><p>The &quot;<strong>limit</strong>&quot; tag outlines the joint&#39;s motion constraints, including maximum and minimum angles, torque, and speed limits.</p><p>The &quot;<strong>dynamics</strong>&quot; tag specifies the joint&#39;s dynamic parameters, such as damping and friction.</p><img loading="lazy" height="282" width="713" class="common_img" src="'+Q+'"><p>(4) gazebo.xacro Analysis</p><p>This is mainly used for creating robot models in the Gazebo simulator. It defines the physical attributes, joint control, sensors, and other details for different robot components, enabling simulation, control, and testing in Gazebo. Since the code is long, we&#39;ll break it down into three sections and provide examples for each. These sections primarily include the following:</p><p>① Gazebo tag</p><p>This section defines two Gazebo plugins: &quot;<strong>gazebo_ros_control</strong>&quot; and &quot;<strong>imu_plugin</strong>&quot; The &quot;<strong>gazebo_ros_control</strong>&quot; plugin enables joint control for the robot, while the &quot;<strong>imu_plugin</strong>&quot; simulates an Inertial Measurement Unit (IMU) sensor</p><img loading="lazy" height="820" width="719" class="common_img" src="'+P+'"><p>② sensor Tag of gazebo tag</p><p>This tag defines a camera sensor attached to a specific Gazebo link (camera_link). The sensor generates images and publishes them to the ROS topic &quot;<strong>/image_raw</strong>,&quot; while also sending messages with camera parameters to the ROS topic &quot;<strong>/camera_info</strong>.&quot;</p><img loading="lazy" height="548" width="746" class="common_img" src="'+H+'"><img loading="lazy" height="535" width="731" class="common_img" src="'+Y+'"><p>③ Other Tags Under the Gazebo Section</p><p>These tags describe how different parts of the robot behave in the Gazebo simulator by defining their physical traits. For instance, mu1 and mu2 properties control friction, kp and kd properties manage spring and damping effects in connectors, and the material attribute sets the material of links in the Gazebo simulator. The selfCollide attribute indicates whether self-collisions are allowed for that link</p><img loading="lazy" height="188" width="606" class="common_img" src="'+L+'"><p>(5) materials.xacro analysis</p><p>This &quot;<strong>materials.xacro</strong>&quot; file defines some materials used in the Gazebo simulation environment. Each material has a name and an RGBA color value. In Gazebo, materials are defined in Xacro-format XML files and can be included in other Xacro files using the &lt;include&gt; tag. These materials can be applied to various parts of a model, like surfaces, edges, etc., to enhance the model&#39;s appearance. Here&#39;s an explanation and examples of the code in this file:</p><img loading="lazy" height="529" width="716" class="common_img" src="'+J+'"><p>In the above code, each material has a name like &quot;<strong>black</strong>&quot;, &quot;<strong>blue</strong>&quot;, &quot;<strong>green</strong>&quot;, etc., which can be referenced in other files. Each material also has an RGBA color value where &quot;<strong>rgba</strong>&quot; stands for red, green, blue, and transparency, with values ranging from 0 to 1.</p><p>The code in this file is relatively simple; it merely defines some common colors. In real projects, you might need to define more colors or other attributes.</p><p>(6) transmissions.xacro Analysis</p><p>The &quot;<strong>transmissions.xacro</strong>&quot; file defines the transmission system within the robot model, including how various joints and motors interact. It uses Xacro language to define different aspects of the transmission system, including transmission types, joints, and motors. During runtime, ROS converts the &quot;<strong>transmissions.xacro</strong>&quot; file into the transmission system of the robot model. It mainly consists of the following two sections</p><p>① Define Transmission Template</p><p>Xacro employs macros defined by &lt;xacro:macro&gt; to create templates for the transmission system. Within this, the &lt;transmission&gt; tag defines the type and name of the transmission system, the &lt;joint&gt; tag specifies the joint driver interface, and the &lt;actuator&gt; tag sets attributes like mechanical reduction ratio.</p><img loading="lazy" height="286" width="711" class="common_img" src="'+Z+'"><p>② Define Transmission in Different Types</p><p>We utilize the &lt;xacro:insert_transmission&gt; tag in Xacro to create various transmission types, passing different joint names for parameterization. For instance, &lt;xacro:insert_transmission name=&quot;l_hip_roll&quot; /&gt; generates a transmission system named &quot;<strong>l_hip_roll_tran</strong>.&quot; It uses the EffortJointInterface to drive the &quot;<strong>l_hip_roll</strong>&quot; joint and has a mechanical reduction ratio of 1.</p><img loading="lazy" height="616" width="695" class="common_img" src="'+V+'"><h2 id="_5-3-gazebo-introduction" tabindex="-1">5.3 Gazebo Introduction <a class="header-anchor" href="#_5-3-gazebo-introduction" aria-label="Permalink to &quot;5.3 Gazebo Introduction&quot;">​</a></h2><h3 id="_5-3-1-gazebo-introduction" tabindex="-1">5.3.1 Gazebo Introduction <a class="header-anchor" href="#_5-3-1-gazebo-introduction" aria-label="Permalink to &quot;5.3.1 Gazebo Introduction&quot;">​</a></h3><p>Gazebo is a 3D dynamic simulator capable of accurately and effectively simulating robots in complex indoor and outdoor environments. Similar to how game engines offer high-fidelity visual simulation, Gazebo provides high-fidelity physical simulation. It also offers a comprehensive set of sensor models and a user-friendly interaction method for both users and programmers.</p><p>(1) Classic uses of Gazebo:</p><p>Testing robot algorithms</p><p>Designing robots</p><p>Conducting regression tests in real-world scenarios</p><p>(2) Key features of Gazebo</p><p>Incorporates multiple physics engines</p><p>Contains a diverse library of robot models and environments</p><p>Offers a variety of sensors</p><p>Provides convenient programming and a simple graphical interface</p><p>(3) Gazebo Official Recommendation</p><p>Gazebo is currently best suited for running on Ubuntu or other Linux distributions. Your computer should have the following capabilities</p><p>A dedicated GPU: Nvidia cards typically perform well on Ubuntu.</p><p>At least an Intel I5 or equivalent CPU.</p><p>A minimum of 500MB of available disk space.</p><p>Installation on the most recent version of Ubuntu Trusty is highly recommended.</p><h3 id="_5-3-2-gazebo-system-structure" tabindex="-1">5.3.2 Gazebo System Structure <a class="header-anchor" href="#_5-3-2-gazebo-system-structure" aria-label="Permalink to &quot;5.3.2 Gazebo System Structure&quot;">​</a></h3><p>Gazebo employs a distributed architecture that includes separate libraries for communication, physical simulation, rendering, sensor generation, and the user interface. Additionally, Gazebo offers two executable programs for running simulations:</p><p>The server, &quot;<strong>gzserver</strong>,&quot; is used for simulating physics, rendering, and sensors.</p><p>The client, &quot;<strong>gzclient</strong>,&quot; provides a graphical interface for visualizing and interacting with simulations.</p><p>The client and server communicate using the Gazebo communication library.</p><p>Gazebo&#39;s Master is akin to the ROS system&#39;s communication mechanism master node, but it operates on topics, offering topic name lookup and management. A single Master can oversee the simulation of multiple physical environments, sensor generation, and graphical interfaces. Gazebo utilizes the following libraries:</p><ul><li><strong>Communication-related Library</strong></li></ul><p>This library serves as Gazebo&#39;s communication and transport mechanism, currently supporting publish/subscribe only. The communication-related library is the foundation for all sub-libraries and is typically included.</p><p>Dependencies: Protobuf and boost::ASIO</p><p>External interface: Supports communication with Gazebo nodes via named topics.</p><p>Internal interface: None.</p><p>Broadcast topics: None.</p><p>Subscribed topics: None.</p><ul><li><strong>Library of Physical Environment</strong></li></ul><p>The physics engine library provides a simple and fundamental interface for the essential aspects of simulation, including rigid bodies, collision shapes, and constraints for joints. This interface is embedded with four open-source physics engines: Open Dynamics Engine (ODE), Bullet, Simbody, and Dynamic Animation and Robotics Toolkit (DART).</p><p>Model description XML files in the SDF format can be loaded by these physics engines. They offer various implementation algorithms and simulation features.</p><p>Dependencies: Depends on the library of the dynamics engine (internal collision detection)</p><p>External interface: Offers a straightforward and generic interface for physical simulation</p><p>Internal interface: Provides the basic interface for third-party dynamic engine-defined physics libraries</p><p>(3) Rendering library</p><p>The rendering library utilizes OGRE to provide a straightforward interface for parsing 3D scenes. It includes the simulation of lighting, textures, and skies, with the ability to write plugins for rendering engines.</p><p>Dependencies: OGRE</p><p>External interface: Permits loading, initialization, and scene creation.</p><p>Internal interface: Stores metadata for visualization, invokes OGRE APIs to achieve model rendering</p><p>(4) Sensor data generation library</p><p>The sensor data generation library allows various types of sensors to monitor updates from the physical environment simulation and generate different data based on the sensor&#39;s characteristics.</p><p>Dependencies: Rendering library and physics engine library.</p><p>External interface: Provides basic sensor initialization and sensor settings.</p><p>Internal interface: To be determined (TBD).</p><p>(5) GUI</p><p>The GUI library uses QT to create graphical widgets for user simulation interaction. Users can control the flow of time by pausing or changing the time step through GUI widgets. They can also modify the scene by adding, altering, or deleting models. Additionally, there are tools for visualizing and recording simulated sensor data.</p><p>Dependencies: Rendering library and QT.</p><p>External interface: None.</p><p>Internal interface: None.</p><h3 id="_5-3-3-gazebo-coordinate-system" tabindex="-1">5.3.3 Gazebo Coordinate System <a class="header-anchor" href="#_5-3-3-gazebo-coordinate-system" aria-label="Permalink to &quot;5.3.3 Gazebo Coordinate System&quot;">​</a></h3><p>Coordinate systems are indispensable for both forward and inverse kinematic analysis. Below, we will use the AiNex robot model in the Gazebo environment as an example to introduce several commonly used coordinate systems.</p><ul><li><strong>Coordinate System</strong></li></ul><p>The World Coordinate System is a stationary reference coordinate system located &#39;<strong>on the ground</strong>&#39;. It doesn&#39;t undergo translation or rotation changes over time. Of course, here &#39;ground&#39; is a generalized term. For example, if a robot is on a table, the world coordinate system is situated on the table.</p><img loading="lazy" height="761" width="1367" class="common_img" src="'+K+'"><ul><li><strong>Joint Coordinate System</strong></li></ul><p>Joint Coordinate System is defined within the leg. Similarly, the establishment of the Joint Coordinate System follows the right-hand rule. Therefore, in the robot model example in the diagram below, the red axis represents the X-axis, the green axis represents the Y-axis, and the blue axis represents the Z-axis.</p><p>The number of Joint Coordinate System is not fixed. It primarily depends on the number of legs.</p><img loading="lazy" height="545" width="959" class="common_img" src="'+W+'"><h3 id="_5-3-4-gazebo-gui-introduction" tabindex="-1">5.3.4 Gazebo GUI Introduction <a class="header-anchor" href="#_5-3-4-gazebo-gui-introduction" aria-label="Permalink to &quot;5.3.4 Gazebo GUI Introduction&quot;">​</a></h3><p>Open the terminal within the Ubuntu system. Execute the following command &quot;<strong>cd /home/ubuntu/ros_ws/src/ainex_simulations/ainex_description/urdf</strong>&quot; to navigate to the folder where URDF models are stored.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cd /home/ubuntu/ros_ws/src/ainex_simulations/ainex_description/urdf</span></span></code></pre></div><p>The simulation interface is as below:</p><img loading="lazy" height="746" width="1303" class="common_img" src="'+_+'"><p>The function of each part is detailed in the table below.</p><table tabindex="0"><thead><tr><th style="text-align:center;">Name</th><th style="text-align:center;">Function</th></tr></thead><tbody><tr><td style="text-align:center;">Menu bar</td><td style="text-align:center;">Configure or modify simulation software parameters and some interactive functions</td></tr><tr><td style="text-align:center;">Tool bar</td><td style="text-align:center;">Provide the most commonly used options when interacting with the simulator</td></tr><tr><td style="text-align:center;">Timestamp</td><td style="text-align:center;">Enable manipulation of time within the virtual space</td></tr><tr><td style="text-align:center;">Action bar</td><td style="text-align:center;">Allow for model manipulation and parameter adjustments</td></tr><tr><td style="text-align:center;">Scenario</td><td style="text-align:center;">Serve as the primary area where the simulation model is displayed</td></tr></tbody></table><h2 id="_5-4-gazebo-simulation-motion-planning" tabindex="-1">5.4 Gazebo Simulation &amp; Motion Planning <a class="header-anchor" href="#_5-4-gazebo-simulation-motion-planning" aria-label="Permalink to &quot;5.4 Gazebo Simulation &amp; Motion Planning&quot;">​</a></h2><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><ul><li><p>Before starting the simulation, ensure that your computer has VMware virtual machine installed. If you haven&#39;t completed the installation, please refer to the tutorial &quot;<strong>Lesson 2 URDF Model Explanation</strong>&quot; for environment setup.</p></li><li><p>All the following operations require coordination with the VM virtual machine, so please make sure to open the virtual machine in advance.</p></li></ul></section><h3 id="_5-4-1-open-terminal-within-virtual-machine" tabindex="-1">5.4.1 Open Terminal within Virtual Machine <a class="header-anchor" href="#_5-4-1-open-terminal-within-virtual-machine" aria-label="Permalink to &quot;5.4.1 Open Terminal within Virtual Machine&quot;">​</a></h3><p>(1) Open VMware, and click-on &quot;<strong>Power on this virtual machine</strong>&quot;.</p><img loading="lazy" height="129" width="314" class="common_img" src="'+$+'"><p>(2) Click-on <img loading="lazy" height="40" width="49" src="'+tt+'"> to open the terminal.</p><img loading="lazy" height="420" width="871" class="common_img" src="'+et+'"><p>(3) Maximize the terminal window, then right-click on it and choose &#39;Split Vertically&#39; to create a new terminal. After that, right-click the new terminal and select &#39;Split Horizontal&#39; to add one more terminal.</p><img loading="lazy" height="606" width="1268" class="common_img" src="'+ot+'"><h3 id="_5-4-2-execute-running-command" tabindex="-1">5.4.2 Execute Running Command <a class="header-anchor" href="#_5-4-2-execute-running-command" aria-label="Permalink to &quot;5.4.2 Execute Running Command&quot;">​</a></h3><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>The following commands need to be executed in sequence.</p></section><p>(1) Three terminals are available.</p><img loading="lazy" height="592" width="1268" class="common_img" src="'+it+'"><p>(2) Execute the command &quot;<strong>roslaunch ainex_gazebo worlds.launch</strong>&quot; on terminal ① to enable the gazebo model.</p><img loading="lazy" height="52" width="648" class="common_img" src="'+nt+'"><p>(3) Run the following command &quot;<strong>python3 software/walking_controller/main.py</strong>&quot; on terminal ② to enable the PC software program. Please note that the PC software will initiated after ROS service is enabled.</p><img loading="lazy" height="48" width="711" class="common_img" src="'+st+'"><p>(4) Execute this command &quot;<strong>roslaunch ainex_kinematics ainex_controller.launch</strong>&quot; on terminal ③ to initiate ROS service. After this service is enabled successfully, PC software can be opened.</p><img loading="lazy" height="46" width="760" class="common_img" src="'+at+'"><p>(5) After the above programs and services have completed running, you will see two applications named &#39;<strong>Gazebo</strong>&#39; and &#39;<strong>walking controller</strong>.</p><img loading="lazy" height="570" width="1268" class="common_img" src="'+rt+'"><h3 id="_5-4-3-start-simulation" tabindex="-1">5.4.3 Start Simulation <a class="header-anchor" href="#_5-4-3-start-simulation" aria-label="Permalink to &quot;5.4.3 Start Simulation&quot;">​</a></h3><p>(1) Click-on <img loading="lazy" height="20" width="15" src="'+lt+'"> on Gazebo window to start simulation, then the robot will transform into bending posture from standing posture.</p><img loading="lazy" height="307" width="854" class="common_img" src="'+ct+'"><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>After starting the simulation, keep an eye on the frame rate (FPS) displayed beneath the Gazebo simulation window. If it drops below &#39;9&#39; FPS, you should consider using a more powerful computer. Otherwise, insufficient computer performance could result in abnormal movements or even falls in the simulation model</p></section><img loading="lazy" height="918" width="1918" class="common_img" src="'+gt+'"><p>(2) Switch to &quot;<strong>walking controller</strong>&quot; window. User can input the motion parameter to control robot&#39;s movements on Gazebo. For example, control the robot to go forward in the speed of 0.05m/s.</p><p>Input &quot;<strong>0.05</strong>&quot; in the field of &quot;<strong>x_move_amplitude</strong>&quot;.</p><img loading="lazy" height="262" width="1096" class="common_img" src="'+ht+'"><p>Click-on &quot;<strong>apply</strong>&quot; and &quot;<strong>start</strong>&quot; button in sequence.</p><img loading="lazy" height="375" width="1101" class="common_img" src="'+dt+'"><p>If you need to make the robot cease movements, click-on &quot;<strong>stop</strong>&quot; button.</p><p>(3) After the parameters are set, you can check the robot&#39;s performance on &quot;<strong>gazebo</strong>&quot; window.</p><img loading="lazy" height="851" width="1394" class="common_img" src="'+mt+'">',269)])])}const St=e(pt,[["render",ut]]);export{kt as __pageData,St as default};
